<section class="panel mb-4"><h2>Automation: <?= IntegrationSettings::get('publishing_enabled',false)?'เปิด':'พักอยู่' ?></h2><p class="small text-secondary">n8n เรียกทำทีละขั้นตามเวลาที่นัดหมาย ใช้ปุ่มด้านล่างสำหรับประมวลผลคิวที่ถึงเวลาหนึ่งขั้นด้วยตนเอง ซึ่งอาจส่งข้อมูลไปยังแพลตฟอร์มจริง</p><form method="post" action="<?= e(url('queue')) ?>"><?= Security::field() ?><input type="hidden" name="action" value="tick_queue"><button class="btn btn-outline-primary" type="submit">ประมวลผลคิวที่ถึงเวลาหนึ่งขั้น</button></form></section>
<section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>คอนเทนต์ / ปลายทาง</th><th>สถานะ</th><th>เวลาไทย / ขั้นตอน</th><th>Remote ID / ข้อผิดพลาด</th><th>ดำเนินการ</th></tr></thead><tbody><?php foreach($jobs as $j): ?><tr><td><a href="<?= e(url('content',['id'=>$j['content_id']])) ?>"><?= e($j['title_internal']) ?></a><small class="d-block text-secondary"><?= e(platform_label($j['platform'])) ?> · <?= e($j['display_name']) ?></small></td><td><span class="badge badge-soft"><?= e(status_label($j['status'])) ?></span></td><td><?= e(thai_date($j['due_at'])) ?><small class="d-block text-secondary"><?= e($j['stage']??'ยังไม่เริ่ม') ?> · <?= e(number_format((int)($j['acknowledged_bytes']??0))) ?> bytes</small></td><td><?= e($j['remote_post_id']??'—') ?><small class="d-block text-danger"><?= e($j['last_error_code']??'') ?></small><?php if($j['remote_url']): ?><a href="<?= e($j['remote_url']) ?>" target="_blank" rel="noopener noreferrer">เปิดวิดีโอ ↗</a><?php endif; ?></td><td><?php if(in_array($j['status'],['RETRY_WAIT','AUTH_REQUIRED','FAILED'],true)): ?><form method="post" action="<?= e(url('queue')) ?>"><?= Security::field() ?><input type="hidden" name="action" value="retry_job"><input type="hidden" name="job_id" value="<?= e($j['id']) ?>"><button class="btn btn-sm btn-light" type="submit">Retry แบบตรวจสถานะ</button></form><?php endif; ?><?php if(in_array($j['status'],['PHASE2_REQUIRED','READY','AUTH_REQUIRED','RETRY_WAIT'],true)&&in_array($j['stage'],[null,'NEW'],true)): ?><form method="post" action="<?= e(url('queue')) ?>" class="mt-2"><?= Security::field() ?><input type="hidden" name="action" value="cancel_job"><input type="hidden" name="job_id" value="<?= e($j['id']) ?>"><button class="btn btn-sm btn-outline-secondary" type="submit">ยกเลิกงาน</button></form><?php endif; ?><?php if($j['status']==='UNKNOWN_REMOTE_STATE'): ?><?php if($j['remote_post_id']): ?><form method="post" action="<?= e(url('queue')) ?>" class="mb-2"><?= Security::field() ?><input type="hidden" name="action" value="reconcile_job"><input type="hidden" name="job_id" value="<?= e($j['id']) ?>"><button class="btn btn-sm btn-outline-primary" type="submit">ตรวจสถานะ Remote ID เดิม</button></form><?php endif; ?><span class="small text-danger">ต้องตรวจผลบนแพลตฟอร์มก่อน ห้ามสร้างโพสต์ใหม่ซ้ำ</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$jobs): ?><p class="text-secondary">ยังไม่มีงานเผยแพร่ อนุมัติคอนเทนต์และกดจัดคิวจากหน้ารายละเอียด</p><?php endif; ?></section>
<div class="notice mt-4">อัปโหลดสำเร็จไม่เท่ากับเผยแพร่สำเร็จ ระบบรอ Processing และตรวจ Privacy/สถานะก่อนแสดง PUBLISHED หากสำเร็จเพียงช่องทางเดียวให้ดูสถานะแยกแต่ละแถว</div><?php endif; ?>
